        uint256 initialAttackerBalance = address(attacker).balance;
        uint256 initialAliceBalance = address(alice).balance;

        // Attacker front-runs by submitting transaction first
        vm.prank(attacker);
        rewardContract.claimReward(5);

        // Verify attacker got the reward
        assertEq(address(attacker).balance, initialAttackerBalance + 5 ether);
        assertTrue(rewardContract.claimed(), "Reward should be claimed");

        // Now Alice's transaction should fail
        vm.prank(alice);
        vm.expectRevert();
        rewardContract.claimReward(5);

        // Verify Alice didn't get any funds
        assertEq(address(alice).balance, initialAliceBalance);
    }

    function testNormalClaim() public {
        uint256 initialAliceBalance = address(alice).balance;

        // Alice claims reward without front-running
        vm.prank(alice);
        rewardContract.claimReward(5);

        // Verify Alice got the reward
        assertEq(address(alice).balance, initialAliceBalance + 5 ether);
        assertTrue(rewardContract.claimed(), "Reward should be claimed");
    }
}
